insert into public.textes (cle, valeur) values ('accueil_intro', 'Objets publicitaires, textile, signalétique, cadeaux gravés et décors de pâtisserie. Composez votre sélection, nous vous envoyons le devis et le bon à tirer.') on conflict (cle) do nothing;
insert into public.textes (cle, valeur) values ('accueil_cta_titre', 'Un projet, un événement, une équipe à habiller ?') on conflict (cle) do nothing;
