insert into public.textes (cle, valeur) values ('infos_intro', 'Tout est fabriqué sur place, de la pièce unique à la série. Chaque produit du catalogue est réalisé avec les machines ci-dessous.') on conflict (cle) do nothing;
insert into public.textes (cle, valeur) values ('pied_presentation', 'Marquage publicitaire, gravure laser, impression UV, 3D, textile et alimentaire.') on conflict (cle) do nothing;
