insert into public.parametres (cle, valeur) values ('logo', '"logo-lazerdeco.jpg"'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('tva', '{"Martinique": 0.085, "Guadeloupe": 0.085, "Guyane": 0}'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('express', '0.2'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('delais', '{"mq-retrait": "Gratuit", "mq-livraison": "Forfait indiqué sur le devis, 24 à 72 h", "gp": "Sur devis selon poids, 3 à 5 jours ouvrés", "gf": "Sur devis selon poids, 5 à 8 jours ouvrés"}'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('email_equipe', '[]'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('site_url', '""'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('accueil', '{"sections": [{"id": "hero", "visible": true}, {"id": "reassurance", "visible": true}, {"id": "univers", "visible": true}, {"id": "selection", "visible": true}, {"id": "techniques", "visible": true}, {"id": "appel", "visible": true}], "banniere": {"actif": false, "texte": "", "lien": "", "couleur": "ora", "debut": null, "fin": null}, "selection": {"titre": "Best-sellers", "refs": []}}'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('seo', '{"titre": "LAZR DECO — Marquage publicitaire et impression personnalisée en Martinique", "description": "Objets publicitaires, textile, signalétique, cadeaux gravés et impression alimentaire, fabriqués en Martinique. Livraison Martinique, Guadeloupe, Guyane."}'::jsonb) on conflict (cle) do nothing;
insert into public.parametres (cle, valeur) values ('modeles_emails', '{"nouvelle_demande": {"pour": "equipe", "actif": true, "sujet": "Nouvelle demande {{numero}} — {{client}}", "corps": "Nouvelle demande de devis {{numero}} de {{client}} {{societe}}.\nMontant estimé : {{total_ttc}} TTC.\n\nOuvrir la demande : {{lien_gestion}}"}, "statut": {"pour": "client", "actif": true, "sujet": "{{marque}} — votre commande {{numero}} : {{statut}}", "corps": "Bonjour {{client}},\n\nVotre commande {{numero}} est maintenant : {{statut}}.\nSuivez-la dans votre espace client : {{lien_client}}\n\nL''équipe {{marque}}"}, "bat": {"pour": "client", "actif": true, "sujet": "{{marque}} — votre BAT pour {{numero}} est prêt", "corps": "Bonjour {{client}},\n\nLe bon à tirer (version {{version}}) de votre commande {{numero}} est disponible.\nValidez-le ou demandez une correction depuis votre espace client : {{lien_client}}\n\nAucune fabrication ne démarre sans votre validation.\n\nL''équipe {{marque}}"}, "bat_reponse": {"pour": "equipe", "actif": true, "sujet": "BAT {{numero}} v{{version}} : {{decision}}", "corps": "{{client}} a répondu au BAT version {{version}} de la commande {{numero}} : {{decision}}.\n{{commentaire}}\n\nOuvrir la commande : {{lien_gestion}}"}, "paiement": {"pour": "client", "actif": true, "sujet": "{{marque}} — paiement reçu pour {{numero}}", "corps": "Bonjour {{client}},\n\nNous avons bien reçu votre paiement de {{montant}} pour la commande {{numero}}.\nMerci !\n\nL''équipe {{marque}}"}}'::jsonb) on conflict (cle) do nothing;
